const kategorie = {
    "Klient": "Label_ID_Z_TWOJEGO_GMAILA",
    "Faktury,Płatności": "Label_ID_Z_TWOJEGO_GMAILA",
    "Praca, Współpraca": "Label_ID_Z_TWOJEGO_GMAILA",
    "Platformy Vinted,Olx,Allegro": "Label_ID_Z_TWOJEGO_GMAILA",
    "Inne": "Label_ID_Z_TWOJEGO_GMAILA"
  };

  const priorytety = {
    "Wysoki": "Label_ID_Z_TWOJEGO_GMAILA",
    "Średni": "Label_ID_Z_TWOJEGO_GMAILA",
    "Niski": "Label_ID_Z_TWOJEGO_GMAILA"
  };

  // normalizacja: małe litery, bez polskich znaków i interpunkcji
  const norm = s => String(s ?? '').toLowerCase()
    .replace(/ł/g, 'l').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, ' ').trim();

  // dopasowanie: najpierw pełna nazwa, potem dowolne słowo kluczowe
  const find = (map, val, fallback) => {
    const v = norm(val);
    const keys = Object.keys(map);
    const hit =
      keys.find(k => norm(k) === v) ||
      keys.find(k => v && norm(k).split(' ').some(w => w.length > 2 && v.includes(w)));
    return map[hit ?? fallback];
  };

  // odpowiedź może być obiektem albo tekstem z JSON-em w środku
  let o = $json.output ?? $json;
  if (typeof o === 'string') {
    const m = o.match(/\{[\s\S]*\}/);
    try { o = JSON.parse(m ? m[0] : o); } catch { o = {}; }
  }

  return {
    json: {
      messageId: $('Nieoznaczone maile').item.json.id,
      labelIds: [
        find(kategorie, o.kategoria, "Inne"),
        find(priorytety, o.priorytet, "Średni")
      ]
    }
  };
